# Read only the PET sheet
df = pd.read_excel(DATA_FILE, sheet_name="PET")

# Extract columns based on tga_guess: x=Temperature (°C), y1=Weight (%), y2=Deriv. Weight (%/°C)
temp_col = "Temperature (°C)"
weight_col = "Weight (%)"
dtg_col = "Deriv. Weight (%/°C)"

temps = df[temp_col].values
weights = df[weight_col].values
dtg = df[dtg_col].values

# Prepare data for ECharts: [x, y] pairs
weight_data = [[float(t), float(w)] for t, w in zip(temps, weights)]
# DTG multiplied by -1 so peaks point up
dtg_data = [[float(t), float(-d)] for t, d in zip(temps, dtg)]

# Find residue at nearest 800 °C
idx_800 = np.argmin(np.abs(temps - 800))
residue_weight = weights[idx_800]
residue_temp = temps[idx_800]
residue_label = f"Residue {residue_weight:.2f}%"

# Find highest DTG peak above 150 °C (after multiplying by -1, find max of -dtg where temp > 150)
mask = temps > 150
if mask.any():
    dtg_neg = -dtg[mask]
    temps_masked = temps[mask]
    idx_peak = np.argmax(dtg_neg)
    peak_temp = temps_masked[idx_peak]
    peak_dtg_val = dtg_neg[idx_peak]
else:
    # Fallback if no data above 150
    peak_temp = 600.0
    peak_dtg_val = 0.0

peak_label = f"{peak_temp:.0f} °C"

